pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 amount, uint256 minDeposit) public {
        // Ensure valid parameters
        vm.assume(caller != address(0));
        vm.assume(amount > 0);

        // Set min deposit
        vm.prank(address(this)); // contract deployer
        // We can't set MinDeposit directly; it's set in constructor. Use bound to limit amount
        amount = bound(amount, 0.001 ether, 1000 ether);

        // Fund the caller (but not through deposit to avoid the min deposit check)
        vm.deal(caller, amount * 2);

        // Have caller deposit enough to have balance
        vm.prank(caller);
        c.Deposit{value: amount}();

        // Get balances before cashout
        uint256 balanceBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(caller);

        // Get withdraw amount (must be <= caller's balance)
        uint256 withdrawAmount = bound(amount, 1, callerBalanceBefore);

        // Call cashout
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // Get balances after
        uint256 balanceAfter = address(c).balance;

        // The rule: if CashOut succeeded, the contract's total ETH balance should not increase
        // (it should decrease by withdrawAmount, or stay same if revert)
        assertTrue(!success || balanceAfter <= balanceBefore);
    }
}

