pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 cashOutAmount) public {
        // Ensure caller has enough ETH (1 ether minimum deposit + for the call)
        vm.assume(depositAmount >= 1 ether);
        vm.assume(caller != address(0));
        vm.deal(caller, depositAmount);

        // Deposit some ETH
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record contract ETH balance before CashOut
        uint256 balanceBefore = address(c).balance;

        // Record caller's balance before CashOut
        uint256 callerBalanceBefore = caller.balance;

        // Attempt CashOut
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashOutAmount));

        // Record contract ETH balance after CashOut
        uint256 balanceAfter = address(c).balance;

        // The general rule: if CashOut succeeded, the decrease in contract balance (balanceBefore - balanceAfter) is at most cashOutAmount
        // If it reverted, balances should be unchanged
        if (success) {
            assertTrue(balanceBefore - balanceAfter <= cashOutAmount);
        } else {
            assertTrue(balanceBefore == balanceAfter);
        }
    }
}

