import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender1, address sender2, uint256 deposit1, uint256 deposit2, uint256 cashOut1, uint256 cashOut2) public {
        vm.assume(sender1 != address(0) && sender2 != address(0) && sender1 != sender2);

        // Fund senders with ETH
        vm.deal(sender1, 10 ether);
        vm.deal(sender2, 10 ether);

        // Bound deposits and cashouts
        deposit1 = bound(deposit1, 1 ether, 5 ether);
        deposit2 = bound(deposit2, 1 ether, 5 ether);
        cashOut1 = bound(cashOut1, 0, deposit1);
        cashOut2 = bound(cashOut2, 0, deposit2);

        // Initial sum of balances is 0
        uint256 sumBefore = 0;

        // deposit by sender1
        vm.prank(sender1);
        c.Deposit{value: deposit1}();

        // deposit by sender2
        vm.prank(sender2);
        c.Deposit{value: deposit2}();

        // snapshot sum after deposits
        uint256 sumAfterDeposits = c.balances(sender1) + c.balances(sender2);
        assertEq(sumAfterDeposits, deposit1 + deposit2);

        // sender1 cashout
        vm.prank(sender1);
        (bool success1,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, cashOut1));

        // sender2 cashout
        vm.prank(sender2);
        (bool success2,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, cashOut2));

        // Both should succeed
        assertTrue(success1);
        assertTrue(success2);

        // General rule: after cashouts, total sum of balances <= sum before cashouts
        uint256 sumFinal = c.balances(sender1) + c.balances(sender2);
        assertTrue(sumFinal <= sumAfterDeposits);
    }
}

