pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount, uint256 deposit) public {
        // Ensure amount is reasonable to avoid overflow; deposit can be anything
        vm.assume(caller != address(0));
        vm.assume(amount <= type(uint256).max - deposit);
        vm.deal(caller, deposit + amount);
        // Pre-fund the contract with some balance to allow cashout
        vm.deal(address(c), amount);
        // First, deposit some ether to give caller a balance
        vm.prank(caller);
        c.Deposit{value: deposit}();
        // Record sum of all balances before CashOut
        // Since we only know caller's balance, we sum over all addresses? We can't enumerate.
        // Instead, use a different invariant: caller's balance change equals amount withdrawn
        // But that's already tried. Let's use a different approach:
        // The total balance of the contract in wei should decrease by exactly _am when CashOut succeeds
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(caller);

        // Call CashOut, may revert if amount > balance
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.CashOut.selector, amount));
        if (success) {
            uint256 contractBalanceAfter = address(c).balance;
            uint256 callerBalanceAfter = c.balances(caller);
            // The contract's ether balance should decrease by exactly the amount withdrawn
            assertTrue(contractBalanceAfter == contractBalanceBefore - amount, "Contract balance mismatch");
            // The caller's internal balance should decrease by amount
            assertTrue(callerBalanceAfter == callerBalanceBefore - amount, "Caller balance mismatch");
        } else {
            // If it reverted, nothing should have changed
            uint256 contractBalanceAfter = address(c).balance;
            uint256 callerBalanceAfter = c.balances(caller);
            assertTrue(contractBalanceAfter == contractBalanceBefore, "Contract balance changed on revert");
            assertTrue(callerBalanceAfter == callerBalanceBefore, "Caller balance changed on revert");
        }
    }
}

