import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount >= 0 ether && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount >= 0 ether && withdrawAmount <= 1000 ether);

        // Fund the caller to allow deposits
        vm.deal(caller, 2000 ether);

        // Call Deposit with the given amount
        vm.prank(caller);
        (bool successDeposit,) = address(c).call{value: depositAmount}(abi.encodeWithSignature("Deposit()"));

        // Now call CashOut
        vm.prank(caller);
        (bool successCashOut,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", withdrawAmount));

        // Compute sum of all balances (we can only read the caller's balance via the public getter)
        uint256 callerBalance = c.balances(caller);
        // We cannot iterate over all addresses, so we use a different invariant:
        // The caller's balance should never exceed the original deposit if CashOut succeeded
        // After a successful CashOut, the caller's balance + withdrawAmount should equal the deposit (if deposit was processed)
        if (depositAmount >= c.MinDeposit()) {
            if (successCashOut) {
                assertTrue(callerBalance + withdrawAmount == depositAmount || callerBalance + withdrawAmount < depositAmount);
            }
        } else {
            // For small deposits, the reference contract rejects them, so balance remains zero
            assertTrue(callerBalance == 0);
        }
    }
}

