import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr, uint256 amount, uint256 depositAmount) public {
        // Bound depositAmount to be >= MinDeposit (1 ether) for reference to accept it
        vm.assume(amount <= type(uint256).max - 1 ether);
        vm.assume(depositAmount >= 1 ether && depositAmount <= type(uint256).max - 1 ether);
        // Fund the contract so CashOut can succeed
        vm.deal(address(c), 10 ether);
        // Do a deposit to increase balances for addr (if we want, but not required for rule)
        // Actually, we want to set up so that addr has some balance after deposit
        vm.prank(addr);
        c.Deposit{value: depositAmount}();

        // Get total balance of all addresses before CashOut (we'll sample a few)
        // Since mapping is not enumerable, we compute sum for addr and another random address
        address other = address(uint160(uint256(keccak256(abi.encode(addr, block.timestamp)))));
        uint256 beforeAddr = c.balances(addr);
        uint256 beforeOther = c.balances(other);

        // Perform CashOut with bounded amount
        vm.assume(amount <= beforeAddr);
        vm.prank(addr);
        c.CashOut(amount);

        uint256 afterAddr = c.balances(addr);
        uint256 afterOther = c.balances(other);

        // Rule: The sum of balances for these two addresses does not increase
        assertTrue((beforeAddr + beforeOther) >= (afterAddr + afterOther));
    }
}

